using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Globalization;
using System.Linq;
using System.Windows.Forms;

namespace LocalFlow {
public sealed class StatPoint {public string Label,Detail;public double Value;public StatPoint(string label,double value,string detail=null){Label=label;Value=value;Detail=detail??label;}}
public sealed class StatsChart : Control {
    StatPoint[] points=new StatPoint[0];readonly List<Rectangle> hits=new List<Rectangle>();int selected=-1;readonly bool horizontal;
    public string Caption;public string Unit="words";public string Empty="No data in this period";
    public StatsChart(string title,bool rows=false){Caption=title;horizontal=rows;DoubleBuffered=true;TabStop=true;BackColor=Color.White;AccessibleName=title;Cursor=Cursors.Hand;Height=232;MouseMove+=(s,e)=>{int index=hits.FindIndex(r=>r.Contains(e.Location));if(index>=0&&index!=selected){selected=index;Invalidate();}};MouseDown+=(s,e)=>Focus();GotFocus+=(s,e)=>Invalidate();LostFocus+=(s,e)=>Invalidate();}
    public void SetPoints(IEnumerable<StatPoint> values){points=values.ToArray();selected=-1;AccessibleDescription=String.Join("; ",points.Select(p=>p.Detail+": "+p.Value.ToString("N0")+" "+Unit));Invalidate();}
    protected override bool IsInputKey(Keys keyData){return keyData==Keys.Left||keyData==Keys.Right||keyData==Keys.Up||keyData==Keys.Down||base.IsInputKey(keyData);}
    protected override void OnKeyDown(KeyEventArgs e){base.OnKeyDown(e);if(points.Length==0)return;int move=e.KeyCode==Keys.Right||e.KeyCode==Keys.Down?1:e.KeyCode==Keys.Left||e.KeyCode==Keys.Up?-1:0;if(move!=0){selected=(selected+move+points.Length)%points.Length;e.Handled=true;Invalidate();}}
    protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);Graphics g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;hits.Clear();using(GraphicsPath shape=Theme.Round(new Rectangle(1,1,Width-3,Height-3),12))using(Pen line=new Pen(Focused?Theme.Accent:Theme.Line))g.DrawPath(line,shape);
        using(Font title=new Font("Segoe UI",11,FontStyle.Bold))TextRenderer.DrawText(g,Caption,title,new Rectangle(18,15,Width-36,25),Theme.Ink,TextFormatFlags.EndEllipsis);
        double max=Math.Max(1,points.Select(p=>p.Value).DefaultIfEmpty(0).Max());using(Font font=new Font("Segoe UI",9)){
            if(points.Length==0||points.All(p=>p.Value==0)){TextRenderer.DrawText(g,Empty,font,new Rectangle(18,65,Width-36,Height-90),Theme.Muted,TextFormatFlags.WordBreak);return;}
            if(horizontal){int rowHeight=Math.Min(31,(Height-85)/Math.Max(1,points.Length));for(int i=0;i<points.Length;i++){int y=51+i*rowHeight;Rectangle row=new Rectangle(18,y,Width-36,rowHeight);hits.Add(row);TextRenderer.DrawText(g,points[i].Label,font,new Rectangle(18,y,112,rowHeight),Theme.Ink,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);int plotWidth=Math.Max(20,Width-230);using(Brush fill=new SolidBrush(selected==i?Theme.Accent:Color.FromArgb(246,173,180)))g.FillRectangle(fill,135,y+8,Math.Max(1,(int)(plotWidth*points[i].Value/max)),8);TextRenderer.DrawText(g,points[i].Value.ToString("N0"),font,new Rectangle(Width-88,y,68,rowHeight),Theme.Muted,TextFormatFlags.Right|TextFormatFlags.VerticalCenter);}}
            else{int left=24,top=59,bottom=Height-64;float step=(Width-48f)/Math.Max(1,points.Length);using(Pen line=new Pen(Theme.Line))g.DrawLine(line,left,bottom,Width-24,bottom);for(int i=0;i<points.Length;i++){Rectangle column=new Rectangle((int)(left+i*step),top,Math.Max(1,(int)step),bottom-top+23);hits.Add(column);int h=(int)((bottom-top)*points[i].Value/max),w=Math.Max(2,(int)(step*.65));Rectangle bar=new Rectangle(column.X+(column.Width-w)/2,bottom-h,w,Math.Max(1,h));using(Brush fill=new SolidBrush(selected==i?Theme.Accent:Color.FromArgb(246,173,180)))g.FillRectangle(fill,bar);int every=Math.Max(1,(int)Math.Ceiling(points.Length/(double)Math.Max(2,Width/80)));if(i%every==0)TextRenderer.DrawText(g,points[i].Label,font,new Rectangle(column.X-15,bottom+5,(int)step+30,20),Theme.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.SingleLine);}}
            string detail=selected>=0&&selected<points.Length?points[selected].Detail+" · "+points[selected].Value.ToString("N0")+" "+Unit:"Hover or use arrow keys";TextRenderer.DrawText(g,detail,font,new Rectangle(18,Height-29,Width-36,22),Theme.Muted,TextFormatFlags.SingleLine|TextFormatFlags.EndEllipsis);
        }
    }
}
public sealed class StatsMetric : Panel {
    readonly Label value,detail;
    public StatsMetric(string title){Height=114;DoubleBuffered=true;value=new Label {Location=new Point(17,14),Size=new Size(170,37),Font=new Font("Segoe UI",23,FontStyle.Bold),AutoEllipsis=true};Label caption=new Label {Text=title,Location=new Point(19,55),Size=new Size(180,23),ForeColor=Theme.Muted,AutoEllipsis=true};detail=new Label {Location=new Point(19,81),Size=new Size(180,22),Font=new Font("Segoe UI",8.5f),ForeColor=Theme.Muted,AutoEllipsis=true};Controls.AddRange(new Control[]{value,caption,detail});Resize+=(s,e)=>{value.Width=caption.Width=detail.Width=Math.Max(20,Width-36);Invalidate();};}
    public void Set(string number,string note=""){value.Text=number;detail.Text=note;}
    protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(GraphicsPath shape=Theme.Round(new Rectangle(1,1,Width-3,Height-3),12))using(Pen line=new Pen(Theme.Line))e.Graphics.DrawPath(line,shape);}
}
public sealed class StatsWindow : Form {
    readonly UsageStore usage;readonly Func<bool> tracking;int range=30;StatsSnapshot snapshot;readonly TableLayoutPanel metrics;
    readonly FlowLayoutPanel body=new FlowLayoutPanel {Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(24,4,24,24)};
    readonly StatsMetric words=new StatsMetric("Words dictated"),sessions=new StatsMetric("Dictations"),saved=new StatsMetric("Time saved · estimate"),speed=new StatsMetric("Words / minute"),input=new StatsMetric("AI input tokens"),output=new StatsMetric("AI output tokens"),total=new StatsMetric("Total AI tokens");
    readonly StatsChart tokenChart=new StatsChart("AI tokens over time") {Unit="tokens"},daily=new StatsChart("Words over time"),apps=new StatsChart("Your apps",true),styles=new StatsChart("Writing styles",true),hours=new StatsChart("Your rhythm · hour of day"),weekdays=new StatsChart("Words by weekday");
    readonly Label overview=new Label {Height=29,ForeColor=Theme.Muted},records=new Label {Height=120,Padding=new Padding(16),BackColor=Theme.Surface},milestones=new Label {Height=88,Padding=new Padding(16),BackColor=Theme.Surface},notes=new Label {Height=64,ForeColor=Theme.Muted,Font=new Font("Segoe UI",9)};
    readonly NumericUpDown baseline=new NumericUpDown {Minimum=10,Maximum=200,Width=65};
    readonly List<Button> ranges=new List<Button>();
    public StatsWindow(UsageStore store,Func<bool> enabled){usage=store;tracking=enabled;Text="Stats";Font=new Font("Segoe UI",10);BackColor=Color.White;Controls.Add(body);
        FlowLayoutPanel filters=new FlowLayoutPanel {Height=43,WrapContents=false,Margin=new Padding(0,0,0,12)};foreach(var choice in new[]{new {Name="7 days",Days=7},new {Name="30 days",Days=30},new {Name="90 days",Days=90},new {Name="All time",Days=0}}){int days=choice.Days;Button button=Theme.Button(choice.Name);button.Tag=days;button.Click+=(s,e)=>{range=days;RefreshStats();};ranges.Add(button);filters.Controls.Add(button);}body.Controls.Add(filters);body.Controls.Add(overview);
        metrics=AddRow(118,words,sessions,saved,speed);body.Controls.Add(daily);AddHeading("Local AI");AddRow(118,input,output,total);body.Controls.Add(tokenChart);AddRow(242,apps,styles);AddHeading("Habits");AddRow(232,weekdays,hours);AddHeading("Personal records");body.Controls.Add(records);AddHeading("Milestones · all time");body.Controls.Add(milestones);
        FlowLayoutPanel calculator=new FlowLayoutPanel {Height=39,WrapContents=false,Margin=new Padding(0,16,0,0)};calculator.Controls.Add(new Label {Text="Your typing speed",AutoSize=true,Margin=new Padding(0,5,12,0)});baseline.Value=usage.Data.TypingWpm;baseline.AccessibleName="Typing speed for time saved estimate";calculator.Controls.Add(baseline);calculator.Controls.Add(new Label {Text="words / min",AutoSize=true,ForeColor=Theme.Muted,Margin=new Padding(8,5,0,0)});body.Controls.Add(calculator);body.Controls.Add(notes);
        baseline.ValueChanged+=(s,e)=>usage.SetTypingSpeed((int)baseline.Value);body.SizeChanged+=(s,e)=>Fit();usage.Changed+=RefreshStats;Fit();RefreshStats();
    }
    void AddHeading(string text){body.Controls.Add(new Label {Text=text,Height=35,Font=new Font("Segoe UI",12,FontStyle.Bold),Margin=new Padding(0,15,0,0),Padding=new Padding(0,4,0,0)});}
    TableLayoutPanel AddRow(int height,params Control[] cards){TableLayoutPanel row=new TableLayoutPanel {Height=height,ColumnCount=cards.Length,RowCount=1,Margin=new Padding(0,0,0,12)};for(int i=0;i<cards.Length;i++){row.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100f/cards.Length));cards[i].Dock=DockStyle.Fill;cards[i].Margin=new Padding(0,0,i==cards.Length-1?0:12,0);row.Controls.Add(cards[i],i,0);}body.Controls.Add(row);return row;}
    void Fit(){int width=Math.Max(630,body.ClientSize.Width-body.Padding.Horizontal-SystemInformation.VerticalScrollBarWidth);foreach(Control child in body.Controls)child.Width=width;if(metrics!=null){int columns=width<840?2:4;if(metrics.ColumnCount!=columns){metrics.SuspendLayout();metrics.ColumnStyles.Clear();metrics.RowStyles.Clear();metrics.ColumnCount=columns;metrics.RowCount=4/columns;for(int i=0;i<columns;i++)metrics.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100f/columns));Control[] cards={words,sessions,saved,speed};for(int i=0;i<cards.Length;i++){metrics.SetCellPosition(cards[i],new TableLayoutPanelCellPosition(i%columns,i/columns));cards[i].Margin=new Padding(0,0,i%columns==columns-1?0:12,6);}metrics.Height=118*(4/columns);metrics.ResumeLayout();}}}
    protected override void OnShown(EventArgs e){base.OnShown(e);Fit();RefreshStats();}
    void RefreshStats(){if(IsDisposed)return;snapshot=StatsSnapshot.Create(usage.Data,range,DateTime.Today);foreach(Button button in ranges){bool active=(int)button.Tag==range;button.BackColor=active?Color.FromArgb(255,240,242):Color.White;button.ForeColor=active?Theme.Accent:Theme.Ink;}
        string trend=range==0?"Lifetime total":snapshot.PreviousWords>0?((snapshot.Words-snapshot.PreviousWords)/snapshot.PreviousWords*100).ToString("+0;-0;0")+"% vs previous "+range+" days":"No earlier period to compare";words.Set(snapshot.Words.ToString("N0"),trend);sessions.Set(snapshot.Sessions.ToString("N0"),snapshot.Sessions>0?(snapshot.Words/(double)snapshot.Sessions).ToString("0")+" words on average":"Start your first dictation");saved.Set(StatsSnapshot.Duration(snapshot.SavedSeconds((int)baseline.Value)),"Compared with "+baseline.Value+" wpm typing");speed.Set(snapshot.Seconds>0?snapshot.Wpm.ToString("0"):"—",StatsSnapshot.Duration(snapshot.Seconds)+" recorded");input.Set(snapshot.InputTokens.ToString("N0"));output.Set(snapshot.OutputTokens.ToString("N0"));total.Set(snapshot.TotalTokens.ToString("N0"),"Routing + editing + checks");
        overview.Text=(!tracking()?"Tracking paused · ":"")+snapshot.ActiveDays+" active days   ·   "+snapshot.CurrentStreak+" day streak   ·   "+(snapshot.ActiveDays>0?(snapshot.Words/(double)snapshot.ActiveDays).ToString("N0"):"0")+" words / active day";
        DateTime plotStart=range==0?DateTime.Today.AddDays(-89):snapshot.Start;int count=(int)(DateTime.Today-plotStart).TotalDays+1,step=count>31?7:1;List<StatPoint> buckets=new List<StatPoint>(),tokenBuckets=new List<StatPoint>();for(int i=0;i<count;i+=step){DateTime at=plotStart.AddDays(i),end=at.AddDays(Math.Min(step,count-i)-1);long n=snapshot.Days.Where(d=>String.CompareOrdinal(d.Date,at.ToString("yyyy-MM-dd"))>=0&&String.CompareOrdinal(d.Date,end.ToString("yyyy-MM-dd"))<=0).Sum(d=>d.Words);long tokenCount=snapshot.Days.Where(d=>String.CompareOrdinal(d.Date,at.ToString("yyyy-MM-dd"))>=0&&String.CompareOrdinal(d.Date,end.ToString("yyyy-MM-dd"))<=0).Sum(d=>d.InputTokens+d.OutputTokens);tokenBuckets.Add(new StatPoint(at.ToString("MMM d"),tokenCount,at.ToString("MMM d")+(step>1?" – "+end.ToString("MMM d"):"")));buckets.Add(new StatPoint(at.ToString("MMM d"),n,at.ToString("MMM d")+(step>1?" – "+end.ToString("MMM d"):"")));}daily.Caption=range==0?"Words over time · last 90 days":step>1?"Words over time · weekly":"Words over time · daily";daily.SetPoints(buckets);tokenChart.Caption=range==0?"AI tokens over time · last 90 days":step>1?"AI tokens over time · weekly":"AI tokens over time · daily";tokenChart.SetPoints(tokenBuckets);
        apps.SetPoints(snapshot.Apps.Take(5).Select(a=>new StatPoint(a.Name,a.Words,a.Name+" · "+a.Sessions+" dictations")));styles.SetPoints(snapshot.Modes.Take(4).Select(a=>new StatPoint(a.Name,a.Words,a.Name+" · "+a.Sessions+" dictations")));weekdays.SetPoints(Enumerable.Range(0,7).Select(i=>new StatPoint(new[]{"Mon","Tue","Wed","Thu","Fri","Sat","Sun"}[i],snapshot.Weekdays[i])));hours.SetPoints(Enumerable.Range(0,24).Select(i=>new StatPoint(i%6==0?i.ToString("00"):"",snapshot.Hours[i],i.ToString("00")+":00 – "+i.ToString("00")+":59")));
        UsageDay best=snapshot.Days.OrderByDescending(d=>d.Words).FirstOrDefault(d=>d.Words>0);records.Text="Best day    "+(best==null?"—":best.Date+" · "+best.Words.ToString("N0")+" words")+"\nLongest dictation    "+(snapshot.Longest>0?snapshot.Longest.ToString("N0")+" words":"—")+"    ·    Fastest    "+(snapshot.Fastest>0?snapshot.Fastest.ToString("0")+" wpm":"—")+"\nLongest streak · all time    "+snapshot.LongestStreak+" days";
        long[] targets={100,1000,10000,50000,100000,1000000};long next=targets.FirstOrDefault(t=>t>usage.Data.Words);milestones.Text=String.Join("    ",targets.Select(t=>(usage.Data.Words>=t?"✓ ":"○ ")+(t>=1000?(t/1000).ToString("N0")+"k":t.ToString())))+" words\n"+(next>0?(next-usage.Data.Words).ToString("N0")+" words to your next milestone":"One million words. Keep going!")+"    ·    About "+(usage.Data.Words/250d).ToString("N0")+" pages spoken";
        notes.Text="Time saved and pages are estimates (250 words/page). New breakdowns start "+usage.Data.DetailsSince+".\nStats stay on this computer. Manage tracking and reset in System → General.";
    }
    protected override void Dispose(bool disposing){if(disposing)usage.Changed-=RefreshStats;base.Dispose(disposing);}
}
}
